// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/me", wrapper.GetMe)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/estate", wrapper.GetEstate)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/estate/series", wrapper.GetEstateSeries)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/installations", wrapper.ListInstallations)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/repositories", wrapper.ListRepositories)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/repositories/{id}", wrapper.GetRepository)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/repositories/{id}/events", wrapper.ListRepositoryEvents)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/repositories/{id}/runs", wrapper.ListRepositoryRuns)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/repositories/{id}/dependencies", wrapper.ListRepositoryDependencies)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/repositories/{id}/recheck", wrapper.RecheckRepository)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/pull-requests", wrapper.ListPullRequests)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/pull-requests/{repo_id}/{number}", wrapper.GetPullRequest)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/dashboard-items", wrapper.ListDashboardItems)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/packages", wrapper.ListPackages)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/dependencies", wrapper.ListDependencies)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/updates", wrapper.ListUpdates)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/runs", wrapper.ListRuns)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/events", wrapper.ListEvents)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/deliveries", wrapper.ListDeliveries)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/status", wrapper.GetStatus)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/openapi.yaml", wrapper.GetOpenAPI)

	return m
}

