// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListDashboardItems Dependency Dashboard items waiting on a human or a schedule, oldest first.
	// (GET /dashboard-items)
	ListDashboardItems(ctx context.Context, request ListDashboardItemsRequestObject) (ListDashboardItemsResponseObject, error)
	// ListDeliveries Webhook deliveries, newest first, with GitHub's status from the audit.
	// (GET /deliveries)
	ListDeliveries(ctx context.Context, request ListDeliveriesRequestObject) (ListDeliveriesResponseObject, error)
	// ListDependencies Dependencies across the visible repositories.
	// (GET /dependencies)
	ListDependencies(ctx context.Context, request ListDependenciesRequestObject) (ListDependenciesResponseObject, error)
	// GetEstate KPI numbers over the visible owners, or one of them.
	// (GET /estate)
	GetEstate(ctx context.Context, request GetEstateRequestObject) (GetEstateResponseObject, error)
	// GetEstateSeries One metric over time, in daily or hourly buckets.
	// (GET /estate/series)
	GetEstateSeries(ctx context.Context, request GetEstateSeriesRequestObject) (GetEstateSeriesResponseObject, error)
	// ListEvents The audit log, newest first.
	// (GET /events)
	ListEvents(ctx context.Context, request ListEventsRequestObject) (ListEventsResponseObject, error)
	// ListInstallations The visible installations, with budget readings from their latest runs.
	// (GET /installations)
	ListInstallations(ctx context.Context, request ListInstallationsRequestObject) (ListInstallationsResponseObject, error)
	// GetMe The caller's identity, visible owners and operator flag.
	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// GetOpenAPI This contract.
	// (GET /openapi.yaml)
	GetOpenAPI(ctx context.Context, request GetOpenAPIRequestObject) (GetOpenAPIResponseObject, error)
	// ListPackages Pending updates grouped by package (purl without version), most repositories first.
	// (GET /packages)
	ListPackages(ctx context.Context, request ListPackagesRequestObject) (ListPackagesResponseObject, error)
	// ListPullRequests Renovate's pull requests, oldest opened first.
	// (GET /pull-requests)
	ListPullRequests(ctx context.Context, request ListPullRequestsRequestObject) (ListPullRequestsResponseObject, error)
	// GetPullRequest One pull request with its updates and timeline.
	// (GET /pull-requests/{repo_id}/{number})
	GetPullRequest(ctx context.Context, request GetPullRequestRequestObject) (GetPullRequestResponseObject, error)
	// ListRepositories Onboarded and offboarded repositories, by slug.
	// (GET /repositories)
	ListRepositories(ctx context.Context, request ListRepositoriesRequestObject) (ListRepositoriesResponseObject, error)
	// GetRepository One repository, with its live state from Temporal when reachable.
	// (GET /repositories/{id})
	GetRepository(ctx context.Context, request GetRepositoryRequestObject) (GetRepositoryResponseObject, error)
	// ListRepositoryDependencies The repository's current dependencies, from its latest run with a report.
	// (GET /repositories/{id}/dependencies)
	ListRepositoryDependencies(ctx context.Context, request ListRepositoryDependenciesRequestObject) (ListRepositoryDependenciesResponseObject, error)
	// ListRepositoryEvents The repository's timeline, newest first.
	// (GET /repositories/{id}/events)
	ListRepositoryEvents(ctx context.Context, request ListRepositoryEventsRequestObject) (ListRepositoryEventsResponseObject, error)
	// RecheckRepository Ask the repository's workflow for a run now.
	// (POST /repositories/{id}/recheck)
	RecheckRepository(ctx context.Context, request RecheckRepositoryRequestObject) (RecheckRepositoryResponseObject, error)
	// ListRepositoryRuns The repository's runs, newest first.
	// (GET /repositories/{id}/runs)
	ListRepositoryRuns(ctx context.Context, request ListRepositoryRunsRequestObject) (ListRepositoryRunsResponseObject, error)
	// ListRuns Runs across the visible repositories, newest first.
	// (GET /runs)
	ListRuns(ctx context.Context, request ListRunsRequestObject) (ListRunsResponseObject, error)
	// GetStatus Public service status.
	// (GET /status)
	GetStatus(ctx context.Context, request GetStatusRequestObject) (GetStatusResponseObject, error)
	// ListUpdates Proposed updates from the latest runs; the correlator's entry point.
	// (GET /updates)
	ListUpdates(ctx context.Context, request ListUpdatesRequestObject) (ListUpdatesResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

